import pyomo.environ as pyo

DATA = {
    "bin_types": ["small", "large"],
    "workers_per_bin": {"small": 2, "large": 5},
    "capacity_per_bin": {"small": 25, "large": 60},
    "workers_available": 100,
    "small_to_large_ratio": 3,   # small bins = 3 * large bins
    "min_small_bins": 10,
    "min_large_bins": 4,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.BIN = pyo.Set(initialize=d["bin_types"])

    # Variables
    def small_bounds(m):
        return (d["min_small_bins"], None)

    def large_bounds(m):
        return (d["min_large_bins"], None)

    model.bins = pyo.Var(
        model.BIN,
        within=pyo.NonNegativeIntegers,
        bounds=lambda m, b: (d["min_small_bins"], None)
        if b == "small"
        else (d["min_large_bins"], None),
    )

    # Objective: maximize total recycling material collected
    def obj_rule(m):
        return sum(d["capacity_per_bin"][b] * m.bins[b] for b in m.BIN)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: worker availability
    def worker_rule(m):
        return sum(d["workers_per_bin"][b] * m.bins[b] for b in m.BIN) <= d["workers_available"]

    model.worker_limit = pyo.Constraint(rule=worker_rule)

    # Constraint: small bins must equal three times large bins
    def ratio_rule(m):
        return m.bins["small"] - d["small_to_large_ratio"] * m.bins["large"] == 0

    model.ratio = pyo.Constraint(rule=ratio_rule)

    return model


